/// Workout models — plans, days, and logged sessions.
library;

import 'package:cloud_firestore/cloud_firestore.dart';
import 'exercise.dart';

/// Weekly workout plan generated by AI
class WorkoutPlan {
  final String id;
  final String userId;
  final String splitType; // PPL, Upper/Lower, Full Body, etc.
  final int weekNumber;
  final List<WorkoutDay> days;
  final DateTime createdAt;

  WorkoutPlan({
    required this.id,
    required this.userId,
    required this.splitType,
    this.weekNumber = 1,
    required this.days,
    DateTime? createdAt,
  }) : createdAt = createdAt ?? DateTime.now();

  Map<String, dynamic> toFirestore() => {
        'id': id,
        'userId': userId,
        'splitType': splitType,
        'weekNumber': weekNumber,
        'days': days.map((d) => d.toMap()).toList(),
        'createdAt': Timestamp.fromDate(createdAt),
      };

  factory WorkoutPlan.fromFirestore(Map<String, dynamic> data) {
    return WorkoutPlan(
      id: data['id'] ?? '',
      userId: data['userId'] ?? '',
      splitType: data['splitType'] ?? 'PPL',
      weekNumber: data['weekNumber'] ?? 1,
      days: (data['days'] as List<dynamic>?)
              ?.map((d) => WorkoutDay.fromMap(d as Map<String, dynamic>))
              .toList() ??
          [],
      createdAt: (data['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),
    );
  }
}

/// A single day in the workout plan
class WorkoutDay {
  final String name; // "Push Day", "Leg Day", "Rest"
  final int dayIndex; // 0=Monday, 6=Sunday
  final List<PlannedExercise> exercises;
  final int estimatedMinutes;
  final double estimatedVolume; // kg

  const WorkoutDay({
    required this.name,
    required this.dayIndex,
    this.exercises = const [],
    this.estimatedMinutes = 60,
    this.estimatedVolume = 0,
  });

  Map<String, dynamic> toMap() => {
        'name': name,
        'dayIndex': dayIndex,
        'exercises': exercises.map((e) => e.toMap()).toList(),
        'estimatedMinutes': estimatedMinutes,
        'estimatedVolume': estimatedVolume,
      };

  factory WorkoutDay.fromMap(Map<String, dynamic> data) {
    return WorkoutDay(
      name: data['name'] ?? 'Workout',
      dayIndex: data['dayIndex'] ?? 0,
      estimatedMinutes: data['estimatedMinutes'] ?? 60,
      estimatedVolume: (data['estimatedVolume'] ?? 0).toDouble(),
    );
  }
}

/// A logged workout session
class WorkoutLog {
  final String id;
  final String userId;
  final String workoutDayName;
  final DateTime date;
  final int durationMinutes;
  final double totalVolume; // kg
  final List<ExerciseLog> exercises;
  final String? notes;

  WorkoutLog({
    required this.id,
    required this.userId,
    required this.workoutDayName,
    required this.date,
    required this.durationMinutes,
    required this.totalVolume,
    this.exercises = const [],
    this.notes,
  });

  Map<String, dynamic> toFirestore() => {
        'id': id,
        'userId': userId,
        'workoutDayName': workoutDayName,
        'date': Timestamp.fromDate(date),
        'durationMinutes': durationMinutes,
        'totalVolume': totalVolume,
        'exercises': exercises.map((e) => e.toMap()).toList(),
        'notes': notes,
      };

  factory WorkoutLog.fromFirestore(Map<String, dynamic> data) {
    return WorkoutLog(
      id: data['id'] ?? '',
      userId: data['userId'] ?? '',
      workoutDayName: data['workoutDayName'] ?? '',
      date: (data['date'] as Timestamp?)?.toDate() ?? DateTime.now(),
      durationMinutes: data['durationMinutes'] ?? 0,
      totalVolume: (data['totalVolume'] ?? 0).toDouble(),
      exercises: (data['exercises'] as List<dynamic>?)
              ?.map((e) => ExerciseLog.fromMap(e as Map<String, dynamic>))
              .toList() ??
          [],
      notes: data['notes'],
    );
  }
}

/// Logged data for a single exercise in a session
class ExerciseLog {
  final String exerciseId;
  final String exerciseName;
  final List<SetLog> sets;
  final double? rpe;
  final String? note;

  const ExerciseLog({
    required this.exerciseId,
    required this.exerciseName,
    this.sets = const [],
    this.rpe,
    this.note,
  });

  double get totalVolume =>
      sets.fold(0.0, (sum, s) => sum + (s.weightKg * s.reps));

  Map<String, dynamic> toMap() => {
        'exerciseId': exerciseId,
        'exerciseName': exerciseName,
        'sets': sets.map((s) => s.toMap()).toList(),
        'rpe': rpe,
        'note': note,
      };

  factory ExerciseLog.fromMap(Map<String, dynamic> data) {
    return ExerciseLog(
      exerciseId: data['exerciseId'] ?? '',
      exerciseName: data['exerciseName'] ?? '',
      sets: (data['sets'] as List<dynamic>?)
              ?.map((s) => SetLog.fromMap(s as Map<String, dynamic>))
              .toList() ??
          [],
      rpe: data['rpe']?.toDouble(),
      note: data['note'],
    );
  }
}

/// A single set within an exercise log
class SetLog {
  final int setNumber;
  final double weightKg;
  final int reps;
  final bool completed;

  const SetLog({
    required this.setNumber,
    required this.weightKg,
    required this.reps,
    this.completed = true,
  });

  Map<String, dynamic> toMap() => {
        'setNumber': setNumber,
        'weightKg': weightKg,
        'reps': reps,
        'completed': completed,
      };

  factory SetLog.fromMap(Map<String, dynamic> data) {
    return SetLog(
      setNumber: data['setNumber'] ?? 0,
      weightKg: (data['weightKg'] ?? 0).toDouble(),
      reps: data['reps'] ?? 0,
      completed: data['completed'] ?? true,
    );
  }
}
